INSERT INTO legal_documents(id,organization_id,kind,status,version,title,body,body_json,effective_at,updated_by,updated_at,published_by,published_at) SELECT 'legal-demo-terms-1','org-demo','terms','published',COALESCE((SELECT max(version) FROM legal_documents WHERE organization_id='org-demo' AND kind='terms'),0)+1,'Términos y condiciones de la demostración','Estos términos ficticios de Colegio Horizonte describen el uso de la plataforma de demostración: cada cuenta pertenece a una persona del equipo, los estudiantes entran con un código de sección y los datos se usan solo para enseñar y coordinar. Al publicarse una versión nueva, cada persona la acepta en su siguiente ingreso.','{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Uso de la plataforma"}]},{"type":"paragraph","content":[{"type":"text","text":"Estos términos ficticios de Colegio Horizonte describen el uso de la plataforma de demostración: cada cuenta pertenece a una persona del equipo, los estudiantes entran con un código de sección y los datos se usan solo para enseñar y coordinar. Al publicarse una versión nueva, cada persona la acepta en su siguiente ingreso."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuentas y estudiantes"}]},{"type":"paragraph","content":[{"type":"text","text":"Las cuentas son individuales. Los estudiantes no necesitan una: entran con el código de su sección."}]}]}','2026-10-01','user-0','2026-10-01T12:00:00.000Z','user-0','2026-10-01T12:00:00.000Z' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo') AND NOT EXISTS(SELECT 1 FROM legal_documents WHERE id='legal-demo-terms-1');
INSERT INTO legal_documents(id,organization_id,kind,status,version,title,body,consent,body_json,effective_at,updated_by,updated_at,published_by,published_at) SELECT 'legal-demo-privacy-1','org-demo','privacy','published',COALESCE((SELECT max(version) FROM legal_documents WHERE organization_id='org-demo' AND kind='privacy'),0)+1,'Política de privacidad de la demostración','Esta política ficticia explica que Colegio Horizonte trata el nombre, el correo y la actividad de cada cuenta para operar la demostración. No se venden datos. Las personas pueden exportar o pedir el cierre de su cuenta. El consentimiento informado se registra con cada versión publicada.','Doy mi consentimiento informado para el tratamiento de mis datos según esta política de demostración.','{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Datos que se tratan"}]},{"type":"paragraph","content":[{"type":"text","text":"Esta política ficticia explica que Colegio Horizonte trata el nombre, el correo y la actividad de cada cuenta para operar la demostración. No se venden datos. Las personas pueden exportar o pedir el cierre de su cuenta. El consentimiento informado se registra con cada versión publicada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Derechos"}]},{"type":"paragraph","content":[{"type":"text","text":"Puedes exportar tus datos o pedir el cierre de la cuenta. Administración atiende la solicitud."}]}]}','2026-10-01','user-0','2026-10-01T12:00:00.000Z','user-0','2026-10-01T12:00:00.000Z' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo') AND NOT EXISTS(SELECT 1 FROM legal_documents WHERE id='legal-demo-privacy-1');
